{
  "contract_version": "domainry-backend-model-v1",
  "items": [
    {
      "module": "project",
      "kind": "project",
      "key": "project",
      "payload": {
        "blueprint": {
          "schema_version": "1",
          "id": "{{PROJECT_ID}}",
          "name": "{{PROJECT_NAME}}",
          "description": "{{PROJECT_DESCRIPTION}}",
          "project_source_layout": "module_v1"
        }
      }
    },
    {
      "module": "core",
      "kind": "requirement",
      "key": "item_lifecycle",
      "payload": {
        "requirement": {
          "statement": "{{REQUIREMENT_STATEMENT}}",
          "acceptance_criteria": [
            "{{ALLOWED_ACCEPTANCE}}",
            "{{DENIED_ACCEPTANCE}}"
          ],
          "behaviors": [
            {
              "key": "submit_item",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "owner": "business_handler",
              "resource_key": "item.submit",
              "rationale": "{{HANDLER_OWNERSHIP_RATIONALE}}",
              "capability_gap": "The command must update the item and create its submission record in one atomic transaction",
              "involved_objects": [
                "item",
                "item_submission"
              ],
              "read_set": [
                "item"
              ],
              "write_set": [
                "item",
                "item_submission"
              ],
              "transaction_requirement": "the item update and submission creation commit or roll back together"
            }
          ]
        }
      }
    },
    {
      "module": "core",
      "kind": "object_relation",
      "key": "item",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "objects",
            "key": "item",
            "value": {
              "name": "Item",
              "description": "{{ITEM_DESCRIPTION}}",
              "fields": [
                {
                  "key": "name",
                  "name": "Name",
                  "type": "text",
                  "required": true,
                  "config": {}
                },
                {
                  "key": "status",
                  "name": "Status",
                  "type": "select",
                  "required": true,
                  "config": {},
                  "options": [
                    {
                      "value": "pending",
                      "label": "Pending"
                    },
                    {
                      "value": "submitted",
                      "label": "Submitted"
                    }
                  ]
                }
              ]
            }
          },
          {
            "collection": "objects",
            "key": "item_submission",
            "value": {
              "name": "Item submission",
              "description": "Durable receipt created atomically with an item submission",
              "fields": [
                {
                  "key": "source_record_id",
                  "name": "Source record",
                  "type": "relation",
                  "required": true,
                  "validation": {
                    "target": "item"
                  },
                  "config": {}
                },
                {
                  "key": "status",
                  "name": "Status",
                  "type": "select",
                  "required": true,
                  "config": {},
                  "options": [
                    {
                      "value": "seeded",
                      "label": "Seeded"
                    },
                    {
                      "value": "recorded",
                      "label": "Recorded"
                    }
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    {
      "module": "core",
      "kind": "actor_role",
      "key": "operator",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/object_relation/item",
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "permissions",
            "key": "item.read",
            "value": {
              "description": "Read items"
            }
          },
          {
            "collection": "permissions",
            "key": "item.create",
            "value": {
              "description": "Create items"
            }
          },
          {
            "collection": "permissions",
            "key": "item.update",
            "value": {
              "description": "Update items"
            }
          },
          {
            "collection": "roles",
            "key": "operator",
            "value": {
              "name": "Operator",
              "permissions": [
                "item.read",
                "item.create",
                "item.update"
              ],
              "record_scope": "all_records",
              "data_permissions": [
                {
                  "object_key": "item",
                  "scope": "all_records",
                  "read": true,
                  "write": true
                },
                {
                  "object_key": "item_submission",
                  "scope": "all_records",
                  "read": false,
                  "write": true
                }
              ]
            }
          },
          {
            "collection": "demo_users",
            "key": "operator_demo",
            "value": {
              "user_id": "operator_demo",
              "name": "Operator Demo",
              "role_key": "operator"
            }
          }
        ]
      }
    },
    {
      "module": "core",
      "kind": "actor_role",
      "key": "viewer",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/object_relation/item",
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "roles",
            "key": "viewer",
            "value": {
              "name": "Viewer",
              "permissions": [
                "item.read"
              ],
              "record_scope": "all_records",
              "data_permissions": [
                {
                  "object_key": "item",
                  "scope": "all_records",
                  "read": true,
                  "write": false
                }
              ]
            }
          },
          {
            "collection": "demo_users",
            "key": "viewer_demo",
            "value": {
              "user_id": "viewer_demo",
              "name": "Viewer Demo",
              "role_key": "viewer"
            }
          }
        ]
      }
    },
    {

      "module": "core",
      "kind": "action_authorization",
      "key": "item.submit",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/actor_role/operator",
        "core/actor_role/viewer",
        "core/object_relation/item",
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "actions",
            "key": "item.submit",
            "value": {
              "name": "Submit item",
              "object_key": "item",
              "kind": "record_operation",
              "audit_event": "item.submitted",
              "payload_fields": [
                {
                  "key": "request_id",
                  "name": "Request ID",
                  "type": "text",
                  "required": true
                }
              ],
              "idempotency_keys": [
                "request_id"
              ],
              "authorization": {
                "allowed_roles": [
                  "operator"
                ]
              },
              "handler": {
                "data_access": [
                  {
                    "object_key": "item",
                    "operations": [
                      "get_for_update",
                      "conditional_update"
                    ]
                  },
                  {
                    "object_key": "item_submission",
                    "operations": [
                      "create"
                    ]
                  }
                ],
                "output": [
                  {
                    "key": "submission_id",
                    "name": "Submission ID",
                    "type": "text",
                    "required": true
                  }
                ]
              }
            }
          }
        ]
      }
    },
    {
      "module": "core",
      "kind": "resource",
      "key": "item_seed_set",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/object_relation/item",
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "seed_records",
            "key": "item_alpha",
            "value": {
              "object_key": "item",
              "data": {
                "name": "{{VISIBLE_SEED_NAME}}",
                "status": "pending"
              }
            }
          },
          {
            "collection": "seed_records",
            "key": "item_submission_seed",
            "value": {
              "object_key": "item_submission",
              "data": {
                "source_record_id": "$record:item_alpha",
                "status": "seeded"
              }
            }
          }
        ]
      }
    },
    {
      "module": "core",
      "kind": "acceptance",
      "key": "item.submit",
      "requirement_keys": [
        "item_lifecycle"
      ],
      "depends_on": [
        "core/action_authorization/item.submit",
        "core/actor_role/operator",
        "core/actor_role/viewer",
        "core/requirement/item_lifecycle"
      ],
      "payload": {
        "emits": [
          {
            "collection": "acceptance_scenarios",
            "key": "item_submit_allowed",
            "value": {
              "name": "Operator submits item",
              "actor": "operator_demo",
              "role_key": "operator",
              "seed_records": [
                "item_alpha"
              ],
              "actions": [
                "item.submit"
              ],
              "expected_outcome": "positive"
            }
          },
          {
            "collection": "acceptance_scenarios",
            "key": "item_submit_denied",
            "value": {
              "name": "Viewer cannot submit item",
              "actor": "viewer_demo",
              "role_key": "viewer",
              "seed_records": [
                "item_alpha"
              ],
              "attempted_actions": [
                "item.submit"
              ],
              "expected_outcome": "denied",
              "expected_error_code": "backend.action.permission_denied"
            }
          }
        ]
      }
    }
  ]
}

